"""MEMBRA CompanyOS — Employee Registry Part A (Employees 1-30)."""
from typing import List
from pydantic import BaseModel
import hashlib


class EmployeeConfig(BaseModel):
    employee_id: str
    name: str
    department_id: str
    title: str
    role: str
    system_prompt: str
    task_prompt: str
    approved_data_sources: List[str]
    tools: List[str]
    wallet_address: str
    wallet_type: str
    permissions: List[str]
    risk_limit: float
    profit_mandate: str
    compliance_constraints: List[str]
    reporting_format: str
    status: str = "active"
    employee_number: int


def _w(name: str, dept: str, idx: int) -> str:
    return f"membra{hashlib.sha256(f'membra-{dept}-{name}-{idx}-watch-only'.encode()).hexdigest()[:32]}{idx:02d}"


